INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'CREA.G4.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'skill', 'essential', 'Posture, finger pads and gentle breath (Grade 4) are the base of tonguing and tone. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
