INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.c', 'outcome', 'essential', 'Keeping time to a song (Grade 3) is what counting games to a musical rhythm need. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
