INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLKPERF', 'skill', 'essential', 'Naming the parts of a folk song performance (Grade 4) gives the words used for dance. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
