INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'CREA.G4.PERFOR.SONGS.EAC', 'skill', 'essential', 'How the EAC anthem is sung (Grade 4) comes before discussing its message. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY.M_WI_STRING_AS_WIND', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY', 'Puts a string instrument (nyatiti, orutu, litungu) in the wind group.', '{"question":"Which of these is a wind instrument?","wrong_answer":"The nyatiti","correct_answer":"The nzumari"}'::jsonb, 'The child knows it is an indigenous instrument and does not ask how the sound is made.', 'Offer "The nyatiti" next to the right answer and ask the question again in a new context.', 'Ask: what do you do to make the sound? Blow, pluck, or hit? Sort five instruments by that one question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY.M_WI_DRUM_AS_WIND', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY', 'Says a drum (ngoma) is a wind instrument because the sound travels through the air.', '{"question":"Which of these is a wind instrument?","wrong_answer":"The ngoma drum","correct_answer":"The siwa horn"}'::jsonb, 'The child links "wind" to air and sound, not to blowing.', 'Offer "The ngoma drum" next to the right answer and ask the question again in a new context.', 'Ask who makes the sound happen: the player''s breath, or the player''s hand on a skin?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY.M_WI_PLAY_PLUCK', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY', 'Says a wind instrument is played by plucking or hitting.', '{"question":"How is the nzumari played?","wrong_answer":"By plucking its strings","correct_answer":"By blowing into it"}'::jsonb, 'The child mixes up the three ways of making sound.', 'Offer "By plucking its strings" next to the right answer and ask the question again in a new context.', 'Sort pictures into blow, pluck and hit, then ask again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY.M_WI_COMMUNITY_MIX', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.IDENTIFY', 'Gives a wind instrument to the wrong community (the nzumari to the Luo or Maasai).', '{"question":"The nzumari is a wind instrument played mainly by which people?","wrong_answer":"The Luo of Nyanza","correct_answer":"The Swahili of the coast"}'::jsonb, 'The child has not met the instrument or the place it belongs to.', 'Offer "The Luo of Nyanza" next to the right answer and ask the question again in a new context.', 'Use a map of Kenya: find the coast and say which instruments come from there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS.M_WI_WOOD_SINGS', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS', 'Thinks the sound comes from the wood or horn itself shaking.', '{"question":"What vibrates to make the sound in a wind instrument?","wrong_answer":"The wood of the instrument","correct_answer":"The air inside the tube"}'::jsonb, 'The child can feel the instrument tingle and thinks that is the sound.', 'Offer "The wood of the instrument" next to the right answer and ask the question again in a new context.', 'Block the end of a pipe with a finger and blow: no sound. The air inside is the singer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS.M_WI_MORE_HOLES_HIGHER', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS', 'Thinks covering more finger holes makes a higher sound.', '{"question":"A player covers more finger holes. What happens to the sound?","wrong_answer":"It gets higher","correct_answer":"It gets lower"}'::jsonb, 'The child thinks "more" means "higher".', 'Offer "It gets higher" next to the right answer and ask the question again in a new context.', 'Cover holes one by one on a bottle-top whistle or recorder and listen to each step go lower.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS.M_WI_MOUTHPIECE_OUT', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS', 'Thinks the mouthpiece is where the sound comes out.', '{"question":"Which part of a wind instrument does the player blow into?","wrong_answer":"The open end at the bottom","correct_answer":"The mouthpiece"}'::jsonb, 'The child links the part by the mouth with the sound, not with the breath going in.', 'Offer "The open end at the bottom" next to the right answer and ask the question again in a new context.', 'Point to where the air goes in and where the sound goes out, using a flute or straw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS.M_WI_HOLES_FOR_AIR', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.PARTS', 'Says the finger holes are only there to let air out.', '{"question":"What do the finger holes of a flute do?","wrong_answer":"They let the air out so the player can breathe","correct_answer":"They change how long the vibrating air is, so the sound changes"}'::jsonb, 'The child sees holes as gaps and not as controls.', 'Offer "They let the air out so the player can breathe" next to the right answer and ask the question again in a new context.', 'Play three notes by covering holes in turn and ask what changed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE.M_WI_SHARE_UNCLEANED', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE', 'Thinks it is fine to pass the instrument to a friend without cleaning the mouthpiece.', '{"question":"Zawadi has just played the flute. Wanjiru wants a turn. What should happen first?","wrong_answer":"Zawadi hands it over at once","correct_answer":"The mouthpiece is wiped or cleaned"}'::jsonb, 'The child sees it as sharing, not as a hygiene matter.', 'Offer "Zawadi hands it over at once" next to the right answer and ask the question again in a new context.', 'Link to sharing a cup: germs travel by mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE.M_WI_STORE_DAMP', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE', 'Thinks a wind instrument is best stored damp or in a wet cloth.', '{"question":"Where should a wooden flute be kept after use?","wrong_answer":"In a wet cloth so it stays fresh","correct_answer":"In a clean, dry safe place"}'::jsonb, 'The child confuses keeping clean with keeping wet.', 'Offer "In a wet cloth so it stays fresh" next to the right answer and ask the question again in a new context.', 'Show a damp wooden stick with mould beside a dry one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE.M_WI_ROUGH_HANDLING', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE', 'Thinks a hard wooden or horn instrument can be dropped or tapped on things because it is strong.', '{"question":"Baraka taps the flute on the desk to the beat. Is this good care?","wrong_answer":"Yes, wood is strong","correct_answer":"No, handle it gently"}'::jsonb, 'The child equates hard with unbreakable.', 'Offer "Yes, wood is strong" next to the right answer and ask the question again in a new context.', 'Ask what happens to a clay pot or a gourd when it is knocked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING.M_WI_HATCH_ONE_DIRECTION', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING', 'Thinks cross-hatching is lines drawn in one direction only.', '{"question":"What is cross-hatching?","wrong_answer":"Lines drawn side by side in one direction","correct_answer":"Lines that cross each other"}'::jsonb, 'The child has seen shading with parallel lines.', 'Offer "Lines drawn side by side in one direction" next to the right answer and ask the question again in a new context.', 'Draw one set of lines, then add a second set across it, and compare the dark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING.M_WI_ETCH_DRAW_ON', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING', 'Thinks etching means drawing the picture on top with a pen.', '{"question":"How do you make the picture in crayon etching?","wrong_answer":"Draw it on top with a pen","correct_answer":"Scratch it through the dark crayon layer"}'::jsonb, 'The child thinks every drawing is made by adding lines.', 'Offer "Draw it on top with a pen" next to the right answer and ask the question again in a new context.', 'Show a scratched dark layer with bright colour underneath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING.M_WI_ETCH_ORDER', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING', 'Puts the dark crayon first and the bright colours on top.', '{"question":"What goes on the paper first in crayon etching?","wrong_answer":"The dark crayon","correct_answer":"The bright crayon colours"}'::jsonb, 'The child does not see that scratching must uncover something.', 'Offer "The dark crayon" next to the right answer and ask the question again in a new context.', 'Ask: what do we want to see after we scratch? It must already be there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE.M_CA5_WI_BLOW_FOOD', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.CARE', 'Plays a wind instrument straight after eating without rinsing the mouth.', '{"question":"You have just eaten mandazi. What should you do before playing your flute?","wrong_answer":"play it straight away","correct_answer":"rinse your mouth first"}'::jsonb, 'The child does not link food in the mouth with dirt in the instrument.', 'Offer "play it straight away" next to the right answer and ask the question again in a new context.', 'Show crumbs on a mouthpiece; they block and dirty it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING.M_CA5_WI_ETCH_LIGHT_TOP', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING', 'Uses light crayon for the top layer, so the scratched lines do not show.', '{"question":"Which colour goes on top in crayon etching?","wrong_answer":"a light colour","correct_answer":"a dark colour (black)"}'::jsonb, 'The child thinks the first and second layer can be any colours.', 'Offer "a light colour" next to the right answer and ask the question again in a new context.', 'Scratch a dark top over bright colours and a light top over bright colours; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.SKILLS.M_FB_TOE_POKE', 'CREA.G5.CREATI.FOOTBALL.SKILLS', 'Thinks a strong kick uses the toes.', '{"question":"Which part of the foot do you use for an instep kick?","wrong_answer":"The toes","correct_answer":"The laces, on top of the foot"}'::jsonb, 'The child pictures a hard "toe poke" from the playground.', 'Offer "The toes" next to the right answer and ask the question again in a new context.', 'Kick a ball gently with toes and then with laces and compare control.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.SKILLS.M_FB_TRAP_SWAP', 'CREA.G5.CREATI.FOOTBALL.SKILLS', 'Mixes up stopping with the inside of the foot and the step trap.', '{"question":"In a step trap, which part of the foot stops the ball?","wrong_answer":"The inside of the foot","correct_answer":"The sole, placed on top of the ball"}'::jsonb, 'Both are called stopping and the child treats them as one.', 'Offer "The inside of the foot" next to the right answer and ask the question again in a new context.', 'Show both slowly: side-on for the inside stop, and from above for the step trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.SKILLS.M_FB_DRIBBLE_FAR', 'CREA.G5.CREATI.FOOTBALL.SKILLS', 'Thinks a straight dribble means kicking the ball far ahead and running after it.', '{"question":"How is a straight dribble done?","wrong_answer":"Kick the ball far ahead and chase it","correct_answer":"Push the ball forward in small touches and keep it close"}'::jsonb, 'The child mixes up dribbling with a long pass.', 'Offer "Kick the ball far ahead and chase it" next to the right answer and ask the question again in a new context.', 'Dribble around cones with small touches and then with big kicks, and compare how often the ball is lost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE.M_FB_PM_GLUE_FIRST', 'CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE', 'Mixes the adhesive in before soaking and pounding the paper.', '{"question":"Which step comes straight after soaking the paper?","wrong_answer":"Mix it with paste","correct_answer":"Pound it into a pulp"}'::jsonb, 'The child thinks glue is what turns paper into pulp.', 'Offer "Mix it with paste" next to the right answer and ask the question again in a new context.', 'Soak and pound without glue first, then add paste, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE.M_FB_PM_SKIP_SOAK', 'CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE', 'Skips the soaking and pounds dry paper.', '{"question":"Why is the paper soaked in water?","wrong_answer":"To make it heavier","correct_answer":"To make it soft enough to pound into pulp"}'::jsonb, 'The child does not see the use of the step.', 'Offer "To make it heavier" next to the right answer and ask the question again in a new context.', 'Try to pound dry paper and wet paper and feel the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE.M_FB_PM_REMOVE_WET', 'CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE', 'Takes the cone off the mould while it is still wet.', '{"question":"When can the cone be taken off the mould?","wrong_answer":"Straight after pressing","correct_answer":"When it is completely dry"}'::jsonb, 'The child is in a hurry to see the result.', 'Offer "Straight after pressing" next to the right answer and ask the question again in a new context.', 'Remove one wet and one dry cone and compare their shape.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.SKILLS.M_CA5_FB_DRIBBLE_LOOK_DOWN', 'CREA.G5.CREATI.FOOTBALL.SKILLS', 'Keeps eyes only on the ball while dribbling, never looking up.', '{"question":"While dribbling, where should you look?","wrong_answer":"only at the ball","correct_answer":"mostly ahead, glancing at the ball"}'::jsonb, 'Beginners lose the ball when they look up, so they stop looking up.', 'Offer "only at the ball" next to the right answer and ask the question again in a new context.', 'Dribble slowly and call out how many fingers the teacher shows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE.M_CA5_FB_PM_THICK_GLUE', 'CREA.G5.CREATI.FOOTBALL.PAPIER_MACHE', 'Makes the paste very thick so the cones dry faster.', '{"question":"Why is papier mâché paste kept smooth and not too thick?","wrong_answer":"thick paste dries faster","correct_answer":"smooth paste soaks into the paper and sticks the layers well"}'::jsonb, 'The child thinks more glue means stronger and quicker.', 'Offer "thick paste dries faster" next to the right answer and ask the question again in a new context.', 'Compare a strip in runny paste and one in thick lumps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.VALUES.M_RH_MINIM_ONE', 'CREA.G5.CREATI.RHYTHM.VALUES', 'Thinks a minim lasts one beat.', '{"question":"How many beats does a minim last?","wrong_answer":"One beat","correct_answer":"Two beats"}'::jsonb, 'The child gives every note one beat.', 'Offer "One beat" next to the right answer and ask the question again in a new context.', 'Clap and count "1, 2" while holding a minim, then "1" for a crotchet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.VALUES.M_RH_PAIR_TWO_BEATS', 'CREA.G5.CREATI.RHYTHM.VALUES', 'Thinks a pair of quavers lasts two beats.', '{"question":"How many beats do a pair of quavers last together?","wrong_answer":"Two beats","correct_answer":"One beat"}'::jsonb, 'The child counts two notes as two beats.', 'Offer "Two beats" next to the right answer and ask the question again in a new context.', 'Clap "ta-te" in the time of one clap and say "two sounds, one beat".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.VALUES.M_RH_REST_NO_TIME', 'CREA.G5.CREATI.RHYTHM.VALUES', 'Thinks a rest takes no time.', '{"question":"How long is a crotchet rest?","wrong_answer":"It takes no time","correct_answer":"One beat of silence"}'::jsonb, 'The child thinks silence is not part of the music.', 'Offer "It takes no time" next to the right answer and ask the question again in a new context.', 'Clap a pattern and hold hands apart on the rest while counting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.VALUES.M_RH_QUAVER_ONE_BEAT_EACH', 'CREA.G5.CREATI.RHYTHM.VALUES', 'Gives each quaver a whole beat.', '{"question":"How long does one quaver last?","wrong_answer":"One beat","correct_answer":"Half a beat"}'::jsonb, 'The child gives every note one beat and ignores the tail.', 'Offer "One beat" next to the right answer and ask the question again in a new context.', 'Compare "taa" (one clap) with "ta-te" (two claps in the same beat).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.NAMES.M_RH_NAME_TAA_AA_SHORT', 'CREA.G5.CREATI.RHYTHM.NAMES', 'Gives the French name taa-aa to the crotchet and taa to the minim.', '{"question":"Which French name is the minim?","wrong_answer":"Taa","correct_answer":"Taa-aa"}'::jsonb, 'The child thinks the longer name belongs to the note with more beats.', 'Offer "Taa" next to the right answer and ask the question again in a new context.', 'Say taa-aa while holding a long clap and ask how many beats it fills.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.NAMES.M_RH_NAME_TATE_ONE', 'CREA.G5.CREATI.RHYTHM.NAMES', 'Thinks ta-te is one sound lasting one beat, like taa.', '{"question":"How many sounds does ta-te have?","wrong_answer":"One sound","correct_answer":"Two sounds"}'::jsonb, 'The child hears it as one word.', 'Offer "One sound" next to the right answer and ask the question again in a new context.', 'Clap each syllable: "ta" then "te" in one beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.NAMES.M_RH_REST_SOUNDED', 'CREA.G5.CREATI.RHYTHM.NAMES', 'Claps or says a name on a rest.', '{"question":"What do you do on a rest in a rhythm pattern?","wrong_answer":"Clap it quietly","correct_answer":"Stay silent for its beats"}'::jsonb, 'The child fills the silence.', 'Offer "Clap it quietly" next to the right answer and ask the question again in a new context.', 'Clap a pattern with a crotchet rest and hold the hands apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.TWO_BEAT.M_RH_COUNT_SOUNDS', 'CREA.G5.CREATI.RHYTHM.TWO_BEAT', 'Counts sounds instead of beats, so ta-te ta-te seems like four beats.', '{"question":"How many beats are in ta-te ta-te?","wrong_answer":"Four beats","correct_answer":"Two beats"}'::jsonb, 'The child counts every syllable.', 'Offer "Four beats" next to the right answer and ask the question again in a new context.', 'Clap the pattern while walking one step for each beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.TWO_BEAT.M_RH_STRONG_SECOND', 'CREA.G5.CREATI.RHYTHM.TWO_BEAT', 'Puts the strong beat on the second beat.', '{"question":"In a two-beat pattern, which beat is strong?","wrong_answer":"The second beat","correct_answer":"The first beat"}'::jsonb, 'The child stresses the end of a phrase.', 'Offer "The second beat" next to the right answer and ask the question again in a new context.', 'Count "ONE two, ONE two" and stamp on the strong beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.TWO_BEAT.M_RH_TWO_BEAT_THREE', 'CREA.G5.CREATI.RHYTHM.TWO_BEAT', 'Accepts a pattern with three beats as a two-beat pattern.', '{"question":"Which pattern fills two beats?","wrong_answer":"Taa taa taa","correct_answer":"Taa ta-te"}'::jsonb, 'The child counts the number of names, not the length.', 'Offer "Taa taa taa" next to the right answer and ask the question again in a new context.', 'Add the beats one by one: taa = 1, ta-te = 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.NAMES.M_CA5_RH_MINIM_TAA', 'CREA.G5.CREATI.RHYTHM.NAMES', 'Says only "taa" for a minim, cutting it to one beat.', '{"question":"What do you say for a minim?","wrong_answer":"taa","correct_answer":"taa-aa, held for two beats"}'::jsonb, 'The child learnt taa first and uses it for every long note.', 'Offer "taa" next to the right answer and ask the question again in a new context.', 'Clap and hold the hands together for the second beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.RHYTHM.TWO_BEAT.M_CA5_RH_BAR_UNEQUAL', 'CREA.G5.CREATI.RHYTHM.TWO_BEAT', 'Puts three beats in one bar and one in the next in a two-beat pattern.', '{"question":"In two-beat time, how many beats go in every bar?","wrong_answer":"any number","correct_answer":"two"}'::jsonb, 'The child draws bar lines where it looks tidy, not by counting.', 'Offer "any number" next to the right answer and ask the question again in a new context.', 'Count 1 2 | 1 2 and draw a line after each 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL.M_PM_GREEN_PRIMARY', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL', 'Calls green a primary colour.', '{"question":"Which of these is a primary colour?","wrong_answer":"Green","correct_answer":"Blue"}'::jsonb, 'Grass and leaves are so green that the child treats it as basic.', 'Offer "Green" next to the right answer and ask the question again in a new context.', 'Mix blue and yellow to make green, so green is made and not basic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL.M_PM_BLACK_WHITE_PRIMARY', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL', 'Calls black or white a primary colour.', '{"question":"Which colours are the primary colours?","wrong_answer":"Black, white and red","correct_answer":"Red, yellow and blue"}'::jsonb, 'The child counts the colours used most in school.', 'Offer "Black, white and red" next to the right answer and ask the question again in a new context.', 'Show that black and white are not on the colour wheel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL.M_PM_SECONDARY_MAKES_PRIMARY', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL', 'Thinks a primary colour can be made by mixing.', '{"question":"Which statement is true?","wrong_answer":"Red can be made by mixing orange and yellow","correct_answer":"Red cannot be made by mixing other colours"}'::jsonb, 'The child believes any colour can be made.', 'Offer "Red can be made by mixing orange and yellow" next to the right answer and ask the question again in a new context.', 'Try to mix red from every pair on the wheel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL.M_PM_ORANGE_PRIMARY', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL', 'Calls orange or purple a primary colour.', '{"question":"Which of these is a secondary colour?","wrong_answer":"Yellow","correct_answer":"Orange"}'::jsonb, 'The child knows orange as a basic fruit colour.', 'Offer "Yellow" next to the right answer and ask the question again in a new context.', 'Mix red and yellow to make orange, then say "made, so secondary".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING.M_PM_MIX_RY_GREEN', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING', 'Says red and yellow make green.', '{"question":"Which two colours make orange?","wrong_answer":"Blue and yellow","correct_answer":"Red and yellow"}'::jsonb, 'The child mixes up the three pairs.', 'Offer "Blue and yellow" next to the right answer and ask the question again in a new context.', 'Paint each pair on a strip and label the result.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING.M_PM_MIX_BY_PURPLE', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING', 'Says blue and yellow make purple.', '{"question":"Which two colours make purple?","wrong_answer":"Blue and yellow","correct_answer":"Red and blue"}'::jsonb, 'The child mixes up the three pairs.', 'Offer "Blue and yellow" next to the right answer and ask the question again in a new context.', 'Paint each pair on a strip and label the result.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING.M_PM_MIX_BROWN', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING', 'Says every mix makes brown.', '{"question":"What colour do red and blue make?","wrong_answer":"Brown","correct_answer":"Purple"}'::jsonb, 'The child has made brown when mixing many colours together.', 'Offer "Brown" next to the right answer and ask the question again in a new context.', 'Mix only two primaries and watch the clean secondary colour appear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH.M_PM_WASH_THICK', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH', 'Thinks a wash is painted with thick paint.', '{"question":"What kind of paint is used for a wash?","wrong_answer":"Thick paint straight from the tube","correct_answer":"Thin, watery paint"}'::jsonb, 'The child thinks strong colour is best.', 'Offer "Thick paint straight from the tube" next to the right answer and ask the question again in a new context.', 'Paint a strip with thick paint and one with water-thinned paint and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH.M_PM_WASH_DETAIL_FIRST', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH', 'Paints the small details first and the large areas last.', '{"question":"In a wash scenery, what is painted last?","wrong_answer":"The sky","correct_answer":"The small details"}'::jsonb, 'The child starts with what is easiest to draw.', 'Offer "The sky" next to the right answer and ask the question again in a new context.', 'Paint the sky first on one page and the details first on another and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH.M_PM_WASH_SMALL_BRUSH', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH', 'Uses the smallest brush for a wash.', '{"question":"Which brush suits a wash over a large area?","wrong_answer":"The smallest, thin brush","correct_answer":"A large, soft brush"}'::jsonb, 'The child thinks a thin brush is more careful.', 'Offer "The smallest, thin brush" next to the right answer and ask the question again in a new context.', 'Cover a page with a thin brush and a large brush and time both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC.M_PM_MOSAIC_PAINTED', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC', 'Thinks a mosaic is painted in tiny dots.', '{"question":"How is a mosaic picture made?","wrong_answer":"By painting tiny dots","correct_answer":"By sticking small pieces of material close together"}'::jsonb, 'The child has seen dotted pictures and thinks of paint.', 'Offer "By painting tiny dots" next to the right answer and ask the question again in a new context.', 'Show a mosaic made of paper bits and seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC.M_PM_MOSAIC_OVERLAP', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC', 'Thinks mosaic pieces should overlap or be stacked.', '{"question":"How should the pieces be placed in a mosaic?","wrong_answer":"On top of each other","correct_answer":"Close together with small gaps"}'::jsonb, 'The child wants to cover the gaps.', 'Offer "On top of each other" next to the right answer and ask the question again in a new context.', 'Compare one mosaic with stacked pieces and one with small gaps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC.M_PM_MOSAIC_NO_PLAN', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC', 'Starts sticking pieces without drawing the design first.', '{"question":"What should be done before sticking the pieces?","wrong_answer":"Glue the whole board at once","correct_answer":"Draw the design on the board"}'::jsonb, 'The child is eager to begin.', 'Offer "Glue the whole board at once" next to the right answer and ask the question again in a new context.', 'Show a mosaic with and without an outline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING.M_CA5_PM_MIX_ALL_THREE', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MIXING', 'Thinks mixing all three primaries makes a bright new secondary.', '{"question":"Red, yellow and blue are mixed together. What do you get?","wrong_answer":"a bright orange","correct_answer":"a dull brown"}'::jsonb, 'The child expects more colours to give a brighter colour.', 'Offer "a bright orange" next to the right answer and ask the question again in a new context.', 'Mix all three on a palette and look.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH.M_CA5_PM_WASH_DRY_PAPER', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.WASH', 'Paints a wash on dry paper with little water and gets hard streaks.', '{"question":"How do you get a smooth wash?","wrong_answer":"use thick paint on dry paper","correct_answer":"wet the paper and use a lot of water with a little paint"}'::jsonb, 'The child paints the way they paint small details.', 'Offer "use thick paint on dry paper" next to the right answer and ask the question again in a new context.', 'Paint a wash on dry and on damp paper; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC.M_CA5_PM_MOSAIC_NO_GAPS', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.MOSAIC', 'Pushes mosaic pieces together with no gaps at all.', '{"question":"In a mosaic, should the pieces touch with no gaps?","wrong_answer":"yes, no gaps","correct_answer":"no; leave small even gaps between pieces"}'::jsonb, 'The child copies montage, where gaps are not wanted.', 'Offer "yes, no gaps" next to the right answer and ask the question again in a new context.', 'Show a mosaic: the gaps make the pattern clear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL.M_CA5_PM_SECONDARY_NEXT', 'CREA.G5.CREATI.PAINTING_AND_MOSAIC.COLOUR_WHEEL', 'Places a secondary colour next to another secondary on the wheel instead of between its two primaries.', '{"question":"On the colour wheel, where is green?","wrong_answer":"next to orange","correct_answer":"between blue and yellow"}'::jsonb, 'The child learns the colours as a list, not as a mixing map.', 'Offer "next to orange" next to the right answer and ask the question again in a new context.', 'Draw the wheel and place each secondary between its two parents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SOLFA.M_ML_FIRST_HIGHEST', 'CREA.G5.CREATI.MELODY.SOLFA', 'Thinks d is the highest sound because it comes first.', '{"question":"Which of d r m f s is the highest sound?","wrong_answer":"d","correct_answer":"s"}'::jsonb, 'The child links first with top.', 'Offer "d" next to the right answer and ask the question again in a new context.', 'Sing d r m f s as steps climbing up a ladder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SOLFA.M_ML_ORDER_SCRAMBLED', 'CREA.G5.CREATI.MELODY.SOLFA', 'Mixes the order of the syllables (d m r f s or d r f m s).', '{"question":"Which is the right order going up?","wrong_answer":"d m r f s","correct_answer":"d r m f s"}'::jsonb, 'The child has learned the names but not the steps.', 'Offer "d m r f s" next to the right answer and ask the question again in a new context.', 'Sing and show with the hand going up step by step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SOLFA.M_ML_DOWN_UP_SAME', 'CREA.G5.CREATI.MELODY.SOLFA', 'Says the order going down is the same as going up.', '{"question":"Which is the order going down from s?","wrong_answer":"s f m r d","correct_answer":"d r m f s"}'::jsonb, 'The child recites the same order every time.', 'Offer "s f m r d" next to the right answer and ask the question again in a new context.', 'Walk down steps while singing the syllables backwards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SIGNS.M_ML_SIGN_FA_UP', 'CREA.G5.CREATI.MELODY.SIGNS', 'Says the sign for f is a thumb pointing up.', '{"question":"Which sol-fa syllable is shown by the thumb pointing down?","wrong_answer":"m","correct_answer":"f"}'::jsonb, 'The child links thumbs with "up".', 'Offer "m" next to the right answer and ask the question again in a new context.', 'Show the sign and say "fa" with the thumb down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SIGNS.M_ML_SIGN_D_OPEN', 'CREA.G5.CREATI.MELODY.SIGNS', 'Thinks the sign for d is an open hand.', '{"question":"How does the hand look for the syllable d?","wrong_answer":"An open, flat hand","correct_answer":"A closed fist, held low"}'::jsonb, 'The child links the first note with the "start" of a greeting.', 'Offer "An open, flat hand" next to the right answer and ask the question again in a new context.', 'Make a fist for d at waist height, then show how the hand opens as notes rise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SIGNS.M_ML_SIGN_SAME_HEIGHT', 'CREA.G5.CREATI.MELODY.SIGNS', 'Thinks all the signs are shown at the same height.', '{"question":"As you go from d to s, how does the hand height change?","wrong_answer":"It stays the same","correct_answer":"It goes higher as the pitch goes higher"}'::jsonb, 'The child focuses on the shape and not the height.', 'Offer "It stays the same" next to the right answer and ask the question again in a new context.', 'Sing d r m f s while the hand rises step by step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.TECHNIQUES.M_ML_STEP_LEAP', 'CREA.G5.CREATI.MELODY.TECHNIQUES', 'Calls a jump from d to m a step.', '{"question":"The melody goes d m. What is this?","wrong_answer":"Stepwise motion","correct_answer":"A narrow leap"}'::jsonb, 'The child counts the syllables, not the gap.', 'Offer "Stepwise motion" next to the right answer and ask the question again in a new context.', 'Sing d r m and d m and show the missing r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.TECHNIQUES.M_ML_REPEAT_NEW', 'CREA.G5.CREATI.MELODY.TECHNIQUES', 'Thinks repeating a pitch means moving to a new pitch.', '{"question":"The melody goes m m m. What technique is used?","wrong_answer":"Stepwise motion","correct_answer":"Repetition of a pitch"}'::jsonb, 'The child thinks each note must be different.', 'Offer "Stepwise motion" next to the right answer and ask the question again in a new context.', 'Sing the same note three times and clap each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.TECHNIQUES.M_ML_END_SHORT', 'CREA.G5.CREATI.MELODY.TECHNIQUES', 'Thinks a melody should end on a short, quick note.', '{"question":"How does a good melody usually end?","wrong_answer":"On a short, quick note","correct_answer":"On a long note"}'::jsonb, 'The child wants to finish quickly.', 'Offer "On a short, quick note" next to the right answer and ask the question again in a new context.', 'Sing a tune ending short and again ending long and ask which feels finished.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SOLFA.M_CA5_ML_F_AFTER_S', 'CREA.G5.CREATI.MELODY.SOLFA', 'Puts s before f when going up the ladder.', '{"question":"Going up, which comes after m: f or s?","wrong_answer":"s","correct_answer":"f"}'::jsonb, 'The child knows the letters but learnt them out of order.', 'Offer "s" next to the right answer and ask the question again in a new context.', 'Sing d r m f s slowly with the ladder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.SIGNS.M_CA5_ML_S_FIST', 'CREA.G5.CREATI.MELODY.SIGNS', 'Shows s as a fist, mixing it with d.', '{"question":"Which syllable is a flat hand facing you?","wrong_answer":"d","correct_answer":"s"}'::jsonb, 'Both d and s are "home" notes in songs, so the child mixes the signs.', 'Offer "d" next to the right answer and ask the question again in a new context.', 'Show d (fist) low and s (flat hand facing you) higher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.MELODY.TECHNIQUES.M_CA5_ML_NO_END_HOME', 'CREA.G5.CREATI.MELODY.TECHNIQUES', 'Ends a short melody on f, so it sounds unfinished.', '{"question":"A melody ends d r m f. Does it sound finished?","wrong_answer":"yes","correct_answer":"no; it should end on d"}'::jsonb, 'The child stops when the notes run out.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Sing it ending on f and ending on d; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.BAT.M_RD_HEAD_HANDLE', 'CREA.G5.CREATI.ROUNDERS.BAT', 'Says the head of the bat is the part you hold.', '{"question":"Which part of a rounders bat hits the ball?","wrong_answer":"The handle","correct_answer":"The head"}'::jsonb, 'The child links "head" with the top and "hold" with the top.', 'Offer "The handle" next to the right answer and ask the question again in a new context.', 'Hold the bat and point to the part that touches the ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.BAT.M_RD_KNOB_HITS', 'CREA.G5.CREATI.ROUNDERS.BAT', 'Thinks the knob is for hitting the ball.', '{"question":"What does the knob at the end of the handle do?","wrong_answer":"It hits the ball","correct_answer":"It stops the bat slipping out of the hand"}'::jsonb, 'The child sees the knob as a hard end.', 'Offer "It hits the ball" next to the right answer and ask the question again in a new context.', 'Swing a bat with and without a knob grip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.BAT.M_RD_CRICKET_FLAT', 'CREA.G5.CREATI.ROUNDERS.BAT', 'Thinks a rounders bat is flat like a cricket bat.', '{"question":"What shape is the head of a rounders bat?","wrong_answer":"Flat on one side like a cricket bat","correct_answer":"Rounded and smooth"}'::jsonb, 'The child knows only cricket.', 'Offer "Flat on one side like a cricket bat" next to the right answer and ask the question again in a new context.', 'Compare a rounders bat and a cricket bat side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.CARVING.M_RD_SANDPAPER_CUTS', 'CREA.G5.CREATI.ROUNDERS.CARVING', 'Says sandpaper is used to cut the wood to length.', '{"question":"Which tool makes the carved bat smooth?","wrong_answer":"The saw","correct_answer":"Sandpaper"}'::jsonb, 'The child ties every tool to cutting.', 'Offer "The saw" next to the right answer and ask the question again in a new context.', 'Match each tool with a finished sample.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.CARVING.M_RD_CUT_TOWARD_BODY', 'CREA.G5.CREATI.ROUNDERS.CARVING', 'Cuts or carves towards the body.', '{"question":"Which is the safe way to carve?","wrong_answer":"Cut towards your body for control","correct_answer":"Cut away from your body"}'::jsonb, 'The child holds the knife close to see better.', 'Offer "Cut towards your body for control" next to the right answer and ask the question again in a new context.', 'Show where the knife goes if it slips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.CARVING.M_RD_FRESH_WOOD', 'CREA.G5.CREATI.ROUNDERS.CARVING', 'Thinks fresh, wet wood is best for a bat.', '{"question":"Which wood suits a bat?","wrong_answer":"Fresh wood just cut from a tree","correct_answer":"Dry hardwood"}'::jsonb, 'The child thinks fresh is better.', 'Offer "Fresh wood just cut from a tree" next to the right answer and ask the question again in a new context.', 'Compare a dry stick and a fresh stick: bend, split and weigh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.SAFETY.M_RD_THROW_BAT', 'CREA.G5.CREATI.ROUNDERS.SAFETY', 'Thinks it is fine to throw the bat after hitting.', '{"question":"What should a batter do with the bat after hitting the ball?","wrong_answer":"Throw it away and run","correct_answer":"Put it down and run"}'::jsonb, 'The child hurries to run.', 'Offer "Throw it away and run" next to the right answer and ask the question again in a new context.', 'Set a target zone for dropped bats and practise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.SAFETY.M_RD_STAND_CLOSE', 'CREA.G5.CREATI.ROUNDERS.SAFETY', 'Stands close to the batter to watch.', '{"question":"Where should fielders and waiting players stand?","wrong_answer":"Close beside the batter to see better","correct_answer":"Well away from the batter"}'::jsonb, 'The child wants a good view.', 'Offer "Close beside the batter to see better" next to the right answer and ask the question again in a new context.', 'Mark a line to stand behind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.SAFETY.M_RD_BOWL_AT_PERSON', 'CREA.G5.CREATI.ROUNDERS.SAFETY', 'Thinks the ball may be thrown hard at a player to get them out.', '{"question":"How should the ball be bowled to the batter?","wrong_answer":"Hard at the batter''s body","correct_answer":"Underarm to the batter"}'::jsonb, 'The child mixes it up with another game.', 'Offer "Hard at the batter''s body" next to the right answer and ask the question again in a new context.', 'Practise underarm bowling at a target.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.BAT.M_CA5_RD_GRIP_TOP', 'CREA.G5.CREATI.ROUNDERS.BAT', 'Holds the bat at the hitting end.', '{"question":"Where do you hold a rounders bat?","wrong_answer":"at the thick end","correct_answer":"at the handle"}'::jsonb, 'The child holds it where it looks strongest.', 'Offer "at the thick end" next to the right answer and ask the question again in a new context.', 'Hold at the handle and swing gently.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.CARVING.M_CA5_RD_NO_MEASURE', 'CREA.G5.CREATI.ROUNDERS.CARVING', 'Starts carving without marking the size and shape on the wood.', '{"question":"What do you do before you start carving the bat?","wrong_answer":"start cutting","correct_answer":"mark the shape and length on the wood"}'::jsonb, 'The child is eager to cut and does not plan.', 'Offer "start cutting" next to the right answer and ask the question again in a new context.', 'Show a bat cut too short without a mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.CREATI.ROUNDERS.SAFETY.M_CA5_RD_RUN_BACKWARD', 'CREA.G5.CREATI.ROUNDERS.SAFETY', 'Runs backwards to watch the ball while running between bases.', '{"question":"Should you run backwards between bases to watch the ball?","wrong_answer":"yes","correct_answer":"no; run forward and look ahead"}'::jsonb, 'The child wants to see the ball.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Show the risk of tripping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.BATON.M_AT_VISUAL_LOOK_AHEAD', 'CREA.G5.PERFOR.ATHLETICS.BATON', 'Thinks a visual baton change means the receiver looks ahead.', '{"question":"In a visual baton change, where does the receiver look?","wrong_answer":"Straight ahead","correct_answer":"Back at the baton"}'::jsonb, 'The child thinks runners always look forward.', 'Offer "Straight ahead" next to the right answer and ask the question again in a new context.', 'Walk through a change slowly and ask where the eyes go.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.BATON.M_AT_NON_VISUAL_STOP', 'CREA.G5.PERFOR.ATHLETICS.BATON', 'Thinks a non-visual change means the runner stops to take the baton.', '{"question":"In a non-visual change, what does the receiver do?","wrong_answer":"Stops and turns round","correct_answer":"Keeps looking ahead and puts a hand back on a signal"}'::jsonb, 'The child links "non-visual" with "not seeing, so not moving".', 'Offer "Stops and turns round" next to the right answer and ask the question again in a new context.', 'Practise at walking speed with eyes ahead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.BATON.M_AT_UP_DOWN_SWAP', 'CREA.G5.PERFOR.ATHLETICS.BATON', 'Swaps upsweep and downsweep.', '{"question":"In an upsweep, which way does the baton move into the hand?","wrong_answer":"Downward","correct_answer":"Upward"}'::jsonb, 'The child mixes up the names.', 'Offer "Downward" next to the right answer and ask the question again in a new context.', 'Show a baton swinging up into a palm and then pressed down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.BATON.M_AT_THROW_BATON', 'CREA.G5.PERFOR.ATHLETICS.BATON', 'Thinks the baton can be thrown to the next runner.', '{"question":"How is the baton passed?","wrong_answer":"Thrown to the next runner","correct_answer":"Placed in the next runner''s hand"}'::jsonb, 'The child wants to save time.', 'Offer "Thrown to the next runner" next to the right answer and ask the question again in a new context.', 'Pass at walking pace and then at a jog.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.RELAY.M_AT_PASS_ANYWHERE', 'CREA.G5.PERFOR.ATHLETICS.RELAY', 'Thinks the baton can be passed anywhere on the track.', '{"question":"Where must the baton be passed in a relay?","wrong_answer":"Anywhere on the track","correct_answer":"Inside the exchange zone"}'::jsonb, 'The child does not know the zone.', 'Offer "Anywhere on the track" next to the right answer and ask the question again in a new context.', 'Mark the zone with cones and practise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.RELAY.M_AT_DROP_LEAVE_IT', 'CREA.G5.PERFOR.ATHLETICS.RELAY', 'Thinks someone else picks up a dropped baton.', '{"question":"The baton is dropped. Who picks it up?","wrong_answer":"The nearest teammate","correct_answer":"The runner who dropped it"}'::jsonb, 'The child wants to save time.', 'Offer "The nearest teammate" next to the right answer and ask the question again in a new context.', 'Practise a drop and pick up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.RELAY.M_AT_FINISH_ANY', 'CREA.G5.PERFOR.ATHLETICS.RELAY', 'Thinks the team has finished when the first of its runners crosses the line.', '{"question":"When has a relay team finished?","wrong_answer":"When any runner crosses the line","correct_answer":"When the last runner crosses the line with the baton"}'::jsonb, 'The child thinks of a normal race.', 'Offer "When any runner crosses the line" next to the right answer and ask the question again in a new context.', 'Run a relay with the team lined up at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.PLAITING.M_AT_PLAIT_TWO', 'CREA.G5.PERFOR.ATHLETICS.PLAITING', 'Says a plait uses two strands.', '{"question":"How many strands are in a plaited rope?","wrong_answer":"Two","correct_answer":"Three"}'::jsonb, 'The child thinks of twisting two strands.', 'Offer "Two" next to the right answer and ask the question again in a new context.', 'Plait with two and three strands and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.PLAITING.M_AT_PLAIT_SAME_STRAND', 'CREA.G5.PERFOR.ATHLETICS.PLAITING', 'Always moves the same strand.', '{"question":"In a plait, how do the strands cross?","wrong_answer":"The same strand goes over each time","correct_answer":"The outer strands cross over the middle one in turn"}'::jsonb, 'The child does not see the pattern.', 'Offer "The same strand goes over each time" next to the right answer and ask the question again in a new context.', 'Colour the three strands differently and plait slowly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.PLAITING.M_AT_PLAIT_UNEQUAL', 'CREA.G5.PERFOR.ATHLETICS.PLAITING', 'Thinks the strands may be of different lengths.', '{"question":"What should the three strands be like at the start?","wrong_answer":"Different lengths","correct_answer":"Equal in length"}'::jsonb, 'The child cuts without measuring.', 'Offer "Different lengths" next to the right answer and ask the question again in a new context.', 'Plait with equal and unequal strands and compare the ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.RELAY.M_CA5_AT_RELAY_RUN_ANY_LANE', 'CREA.G5.PERFOR.ATHLETICS.RELAY', 'Leaves their lane after passing the baton.', '{"question":"After passing the baton, what should you do?","wrong_answer":"run across to the finish","correct_answer":"stay in your lane until the others pass"}'::jsonb, 'The child thinks their job ends at the change.', 'Offer "run across to the finish" next to the right answer and ask the question again in a new context.', 'Walk through a change and show where the next team runs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.ATHLETICS.PLAITING.M_CA5_AT_PLAIT_TIGHT_LOOSE', 'CREA.G5.PERFOR.ATHLETICS.PLAITING', 'Pulls some crossings tight and others loose.', '{"question":"Why pull every crossing of a plait the same?","wrong_answer":"it does not matter","correct_answer":"so the rope is even and strong"}'::jsonb, 'The child focuses on the order and forgets the tension.', 'Offer "it does not matter" next to the right answer and ask the question again in a new context.', 'Compare an even plait and an uneven one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES.M_FD_TD_APPLIQUE_SWAP', 'CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES', 'Swaps tie and dye with appliqué.', '{"question":"Which technique sews cut shapes of cloth onto another cloth?","wrong_answer":"Tie and dye","correct_answer":"Appliqué"}'::jsonb, 'The child has met both words together.', 'Offer "Tie and dye" next to the right answer and ask the question again in a new context.', 'Show a sample of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES.M_FD_APPLIQUE_PAINT', 'CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES', 'Thinks appliqué is painting on cloth.', '{"question":"What is appliqué?","wrong_answer":"Painting a pattern on cloth","correct_answer":"Sewing or sticking cut shapes onto cloth"}'::jsonb, 'The child links decoration with paint.', 'Offer "Painting a pattern on cloth" next to the right answer and ask the question again in a new context.', 'Hold up a painted cloth and an appliqué cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES.M_FD_TIE_DYE_WAX', 'CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES', 'Thinks tie and dye uses wax.', '{"question":"Which technique uses tying to keep dye out?","wrong_answer":"Batik","correct_answer":"Tie and dye"}'::jsonb, 'The child mixes tie and dye with batik.', 'Offer "Batik" next to the right answer and ask the question again in a new context.', 'Show a tied cloth and a wax cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE.M_FD_TD_UNTIE_FIRST', 'CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE', 'Puts the untying before dyeing.', '{"question":"When is the cloth untied in tie and dye?","wrong_answer":"Before dyeing","correct_answer":"After dyeing and rinsing"}'::jsonb, 'The child wants to see the pattern.', 'Offer "Before dyeing" next to the right answer and ask the question again in a new context.', 'Untie too early on a sample.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE.M_FD_TD_TIED_DARK', 'CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE', 'Thinks the tied parts take the most dye.', '{"question":"What colour are the tied parts after dyeing?","wrong_answer":"The darkest dye colour","correct_answer":"Still the cloth''s own colour"}'::jsonb, 'The child thinks tied means squeezed with dye.', 'Offer "The darkest dye colour" next to the right answer and ask the question again in a new context.', 'Dye a tied sample and open it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE.M_FD_TD_NO_FIXER', 'CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE', 'Skips the dye fastener.', '{"question":"Why is a fastener such as salt used?","wrong_answer":"It is not needed","correct_answer":"It helps the dye to stay in the cloth"}'::jsonb, 'The child thinks the colour will stay anyway.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Wash a fixed and an unfixed sample.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE.M_FD_APP_CUT_BACKGROUND', 'CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE', 'Cuts the shape out of the background cloth.', '{"question":"What happens to the background cloth in appliqué?","wrong_answer":"Shapes are cut out of it","correct_answer":"It stays whole and the shapes go on top"}'::jsonb, 'The child thinks of cutting and sewing.', 'Offer "Shapes are cut out of it" next to the right answer and ask the question again in a new context.', 'Show a finished appliqué from the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE.M_FD_APP_LOOSE', 'CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE', 'Leaves the shapes unattached.', '{"question":"How are the shapes held on?","wrong_answer":"They stay loose","correct_answer":"Sewn or stuck round the edges"}'::jsonb, 'The child forgets that cloth slips.', 'Offer "They stay loose" next to the right answer and ask the question again in a new context.', 'Shake a loose and a stitched sample.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE.M_FD_APP_NO_PIN', 'CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE', 'Sews without placing or pinning the shapes first.', '{"question":"What should be done before sewing the shapes?","wrong_answer":"Nothing, start sewing","correct_answer":"Pin or tack them in place"}'::jsonb, 'The child is eager to start.', 'Offer "Nothing, start sewing" next to the right answer and ask the question again in a new context.', 'Sew with and without pinning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES.M_CA5_FD_PRINT_IS_DYE', 'CREA.G5.PERFOR.FABRIC_DECORATION.DECOR_TYPES', 'Calls a printed pattern tie and dye.', '{"question":"A pattern is stamped on cloth with a block. Is it tie and dye?","wrong_answer":"yes","correct_answer":"no; it is printing"}'::jsonb, 'All patterned cloth looks alike to the child.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Show a tie-dye cloth and a printed one side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE.M_CA5_FD_TD_DRY_CLOTH', 'CREA.G5.PERFOR.FABRIC_DECORATION.TIE_DYE', 'Puts dry, unwashed cloth into the dye.', '{"question":"What do you do to the cloth before dyeing it?","wrong_answer":"nothing","correct_answer":"wash it and wet it so the dye spreads evenly"}'::jsonb, 'The child does not know starch and dirt block dye.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Dye a washed and an unwashed strip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE.M_CA5_FD_APP_SAME_COLOUR', 'CREA.G5.PERFOR.FABRIC_DECORATION.APPLIQUE', 'Chooses appliqué pieces the same colour as the background.', '{"question":"Why choose a different colour for appliqué pieces?","wrong_answer":"it does not matter","correct_answer":"so the shapes stand out"}'::jsonb, 'The child matches colours to look neat.', 'Offer "it does not matter" next to the right answer and ask the question again in a new context.', 'Pin a same-colour shape and a contrasting one; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND.M_FN_COMMUNITY_MIX', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND', 'Gives a dance to the wrong community.', '{"question":"The isukuti is a dance of which community?","wrong_answer":"The Maasai","correct_answer":"The Luhya"}'::jsonb, 'The child has not met the dance.', 'Offer "The Maasai" next to the right answer and ask the question again in a new context.', 'Place each dance on a map of Kenya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND.M_FN_SOLOIST_CHORUS_SWAP', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND', 'Swaps the soloist and the chorus.', '{"question":"Who leads the song in a call-and-response dance?","wrong_answer":"The chorus","correct_answer":"The soloist"}'::jsonb, 'The child thinks the largest group leads.', 'Offer "The chorus" next to the right answer and ask the question again in a new context.', 'Perform a call-and-response song.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND.M_FN_OCCASION_SAME', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND', 'Says every dance is performed at the same occasion.', '{"question":"Chakacha is danced mostly at which occasion?","wrong_answer":"Only funerals","correct_answer":"Weddings and celebrations"}'::jsonb, 'The child thinks all dances share one use.', 'Offer "Only funerals" next to the right answer and ask the question again in a new context.', 'List an occasion for each dance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS.M_FN_ORNAMENT_COSTUME', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS', 'Mixes up costume and ornament.', '{"question":"Beads worn on the neck are which component?","wrong_answer":"Costume","correct_answer":"Ornaments"}'::jsonb, 'The child treats everything worn as costume.', 'Offer "Costume" next to the right answer and ask the question again in a new context.', 'Sort pictures into clothes and beads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS.M_FN_PROP_INSTRUMENT', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS', 'Calls a drum a prop.', '{"question":"A drum belongs to which component?","wrong_answer":"Props","correct_answer":"Instruments"}'::jsonb, 'The child thinks anything held or used is a prop.', 'Offer "Props" next to the right answer and ask the question again in a new context.', 'Sort items into those that make music and those that are carried.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS.M_FN_FORMATION_WORN', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS', 'Thinks a formation is something worn.', '{"question":"What is a formation in a dance?","wrong_answer":"A costume worn by dancers","correct_answer":"The shape the dancers make"}'::jsonb, 'The child hears a similar word to "uniform".', 'Offer "A costume worn by dancers" next to the right answer and ask the question again in a new context.', 'Ask the class to stand in a circle and a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES.M_FN_ROLE_FUN_ONLY', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES', 'Says a folk dance is only for fun.', '{"question":"Which is a role of folk dance?","wrong_answer":"Only to pass time","correct_answer":"To hand down culture and values"}'::jsonb, 'The child sees only the performance.', 'Offer "Only to pass time" next to the right answer and ask the question again in a new context.', 'Ask a grandparent why a dance is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES.M_FN_ROLE_OLD_ONLY', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES', 'Says folk dances are only for old people.', '{"question":"Who takes part in folk dances?","wrong_answer":"Only old people","correct_answer":"People of different ages"}'::jsonb, 'The child links tradition with age.', 'Offer "Only old people" next to the right answer and ask the question again in a new context.', 'List who dances in each folk dance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES.M_FN_ROLE_NO_WORK', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES', 'Thinks performing earns no income.', '{"question":"How can folk dance help a community economically?","wrong_answer":"It cannot","correct_answer":"Performers can be paid at events"}'::jsonb, 'The child sees dance as free.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Ask about paid cultural groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY.M_FN_NO_WARMUP', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY', 'Thinks warming up is not needed.', '{"question":"What should dancers do before dancing?","wrong_answer":"Start straight away","correct_answer":"Warm up"}'::jsonb, 'The child is eager to dance.', 'Offer "Start straight away" next to the right answer and ask the question again in a new context.', 'Compare stretched and unstretched dancers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY.M_FN_MOCK_OTHER', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY', 'Laughs at the dance of another community.', '{"question":"A group performs a dance of another community. What is the respectful action?","wrong_answer":"Laugh at the steps","correct_answer":"Watch politely and clap"}'::jsonb, 'The child finds unfamiliar things funny.', 'Offer "Laugh at the steps" next to the right answer and ask the question again in a new context.', 'Ask how it feels when people laugh at your culture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY.M_FN_CROWDED_SPACE', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY', 'Thinks stones and sharp things in the space do not matter.', '{"question":"What should be done to the dancing space?","wrong_answer":"Nothing","correct_answer":"Clear stones and sharp things"}'::jsonb, 'The child ignores the ground.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Walk the space together before dancing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND.M_CA5_FN_DANCE_NEW', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.BACKGROUND', 'Thinks a folk dance was made up recently by a choreographer.', '{"question":"Where does a Kenyan folk dance come from?","wrong_answer":"a dancer made it up last year","correct_answer":"a community, passed down over many years"}'::jsonb, 'The child sees dance on TV made by groups.', 'Offer "a dancer made it up last year" next to the right answer and ask the question again in a new context.', 'Ask an elder or read where the dance comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS.M_CA5_FN_COSTUME_DAILY', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.COMPONENTS', 'Thinks dancers wear school uniform as the costume.', '{"question":"What is a costume in a folk dance?","wrong_answer":"school uniform","correct_answer":"the special dress of the community for the dance"}'::jsonb, 'The child calls any clothes a costume.', 'Offer "school uniform" next to the right answer and ask the question again in a new context.', 'Show pictures of dance costumes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES.M_CA5_FN_ROLE_ONE', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES', 'Thinks a folk dance has only one role, entertainment.', '{"question":"Name a role of folk dance in the community other than fun.","wrong_answer":"there is none","correct_answer":"any of: teaching values, marking ceremonies, passing on history"}'::jsonb, 'The child sees dance only at shows.', 'Offer "there is none" next to the right answer and ask the question again in a new context.', 'List occasions where dance is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY.M_CA5_FN_PROPS_SWING', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.DANCE_SAFETY', 'Swings props wildly near others.', '{"question":"How should props be used in a dance?","wrong_answer":"swing them as hard as you can","correct_answer":"with control, keeping space from others"}'::jsonb, 'The child thinks bigger movement is better dancing.', 'Offer "swing them as hard as you can" next to the right answer and ask the question again in a new context.', 'Practise prop moves slowly in spaces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.TYPES.M_PP_GLOVE_STRING', 'CREA.G5.PERFOR.PUPPETRY.TYPES', 'Says a glove puppet hangs on strings.', '{"question":"How is a glove puppet moved?","wrong_answer":"By strings from above","correct_answer":"By the hand and fingers inside it"}'::jsonb, 'The child mixes up the puppet types.', 'Offer "By strings from above" next to the right answer and ask the question again in a new context.', 'Show both types.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.TYPES.M_PP_GLOVE_FINGER', 'CREA.G5.PERFOR.PUPPETRY.TYPES', 'Thinks a glove puppet fits on one finger only.', '{"question":"Which puppet fits on a single finger?","wrong_answer":"A glove puppet","correct_answer":"A finger puppet"}'::jsonb, 'The child mixes up the two names.', 'Offer "A glove puppet" next to the right answer and ask the question again in a new context.', 'Put each on your hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
