INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.MAKE.M_PP_RECYCLE_NEW', 'CREA.G5.PERFOR.PUPPETRY.MAKE', 'Thinks buying new materials counts as recyclable.', '{"question":"Which is a recyclable material for a puppet?","wrong_answer":"A new, store-bought cloth","correct_answer":"An old sock"}'::jsonb, 'The child thinks recyclable means any material.', 'Offer "A new, store-bought cloth" next to the right answer and ask the question again in a new context.', 'Sort items into used and new.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.MAKE.M_PP_SIZE_NO_FIT', 'CREA.G5.PERFOR.PUPPETRY.MAKE', 'Thinks the puppet need not fit the hand.', '{"question":"Why must a glove puppet fit the hand?","wrong_answer":"It does not need to fit","correct_answer":"So the fingers can move the head and arms"}'::jsonb, 'The child focuses on how it looks.', 'Offer "It does not need to fit" next to the right answer and ask the question again in a new context.', 'Try a puppet that is too big.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.MAKE.M_PP_SHARP_UNSUPERVISED', 'CREA.G5.PERFOR.PUPPETRY.MAKE', 'Uses sharp tools without supervision.', '{"question":"How should scissors or a knife be used while making a puppet?","wrong_answer":"Freely, without help","correct_answer":"Carefully, with an adult watching"}'::jsonb, 'The child feels capable.', 'Offer "Freely, without help" next to the right answer and ask the question again in a new context.', 'Set rules for cutting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.SHOW.M_PP_ALL_MOVE', 'CREA.G5.PERFOR.PUPPETRY.SHOW', 'Moves all puppets at once.', '{"question":"Which puppet moves when it speaks?","wrong_answer":"All puppets move at once","correct_answer":"Only the speaking puppet"}'::jsonb, 'The child is excited.', 'Offer "All puppets move at once" next to the right answer and ask the question again in a new context.', 'Practise with two puppets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.SHOW.M_PP_SHOW_FACE', 'CREA.G5.PERFOR.PUPPETRY.SHOW', 'Thinks the puppeteers should be seen.', '{"question":"Where do the puppeteers stand?","wrong_answer":"In front of the screen","correct_answer":"Behind the screen"}'::jsonb, 'The child wants the audience to see them.', 'Offer "In front of the screen" next to the right answer and ask the question again in a new context.', 'Watch a show with and without a screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.SHOW.M_PP_TOPICAL_ANY', 'CREA.G5.PERFOR.PUPPETRY.SHOW', 'Thinks a topical song is any song.', '{"question":"What is a topical song?","wrong_answer":"Any song we like","correct_answer":"A song about an issue in the community"}'::jsonb, 'The child mixes up topical and popular.', 'Offer "Any song we like" next to the right answer and ask the question again in a new context.', 'List current community issues.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.TYPES.M_CA5_PP_GLOVE_ROD', 'CREA.G5.PERFOR.PUPPETRY.TYPES', 'Calls a puppet on a stick a glove puppet.', '{"question":"A puppet is moved by a stick from below. What type is it?","wrong_answer":"a glove puppet","correct_answer":"a rod puppet"}'::jsonb, 'Both are moved from below.', 'Offer "a glove puppet" next to the right answer and ask the question again in a new context.', 'Show a hand inside a glove puppet and a stick in a rod puppet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.MAKE.M_CA5_PP_NO_FINGER_HOLES', 'CREA.G5.PERFOR.PUPPETRY.MAKE', 'Makes a glove puppet with no places for the fingers to move the head and arms.', '{"question":"Where do your fingers go in a glove puppet?","wrong_answer":"they do not go anywhere","correct_answer":"one finger in the head and fingers in the arms"}'::jsonb, 'The child makes the puppet like a doll.', 'Offer "they do not go anywhere" next to the right answer and ask the question again in a new context.', 'Put a hand in a sample and move the head.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.PUPPETRY.SHOW.M_CA5_PP_ONLY_TALK', 'CREA.G5.PERFOR.PUPPETRY.SHOW', 'Moves the puppet only while it talks and leaves it still the rest of the time.', '{"question":"Should the puppet keep moving while another puppet talks?","wrong_answer":"no, it stays still","correct_answer":"it listens: small nods and turns toward the speaker"}'::jsonb, 'The child thinks moving means talking.', 'Offer "no, it stays still" next to the right answer and ask the question again in a new context.', 'Practise a listening puppet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.NOTES.M_DR_ALPHABET_ORDER', 'CREA.G5.PERFOR.DESCANT_RECORDER.NOTES', 'Puts the notes in alphabet order for pitch.', '{"question":"Which is the lowest of G, A and B?","wrong_answer":"A","correct_answer":"G"}'::jsonb, 'The child orders by letter.', 'Offer "A" next to the right answer and ask the question again in a new context.', 'Play the notes and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.NOTES.M_DR_MORE_HOLES_HIGHER', 'CREA.G5.PERFOR.DESCANT_RECORDER.NOTES', 'Thinks covering more holes gives a higher note.', '{"question":"Which of G, A and B covers the most holes?","wrong_answer":"B","correct_answer":"G"}'::jsonb, 'The child thinks more is higher.', 'Offer "B" next to the right answer and ask the question again in a new context.', 'Cover and uncover holes and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.NOTES.M_DR_HIGH_C_LOW', 'CREA.G5.PERFOR.DESCANT_RECORDER.NOTES', 'Thinks C1 and D1 are lower than G.', '{"question":"Which note is higher than B?","wrong_answer":"G","correct_answer":"C1"}'::jsonb, 'The child does not see the prime mark.', 'Offer "G" next to the right answer and ask the question again in a new context.', 'Sing G A B C D going up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_DR_BLOW_HARD', 'CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Thinks a good tone needs a hard blow.', '{"question":"How should you blow into the recorder?","wrong_answer":"As hard as you can","correct_answer":"Gently and steadily"}'::jsonb, 'The child wants a loud sound.', 'Offer "As hard as you can" next to the right answer and ask the question again in a new context.', 'Blow hard and gently and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_DR_FINGER_TIPS', 'CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Covers the holes with the tips of the fingers.', '{"question":"How should the holes be covered?","wrong_answer":"With the tip of the finger","correct_answer":"With the soft pad of the finger"}'::jsonb, 'The child thinks tips are more precise.', 'Offer "With the tip of the finger" next to the right answer and ask the question again in a new context.', 'Cover the hole with each and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_DR_NO_TONGUE', 'CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Thinks tonguing is not needed.', '{"question":"What does tonguing do?","wrong_answer":"Nothing","correct_answer":"It starts each note clearly"}'::jsonb, 'The child blows without breaks.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Play with and without tonguing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.NOTES.M_CA5_DR_D_ALL_HOLES', 'CREA.G5.PERFOR.DESCANT_RECORDER.NOTES', 'Covers all holes for D''.', '{"question":"How do you play the high D'' on a descant recorder?","wrong_answer":"cover all the holes","correct_answer":"only the second finger of the left hand, thumb off"}'::jsonb, 'The child links D with "many fingers" because low notes need many.', 'Offer "cover all the holes" next to the right answer and ask the question again in a new context.', 'Play D'' with one finger and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_CA5_DR_PUFF_CHEEKS', 'CREA.G5.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Puffs the cheeks to blow.', '{"question":"Should your cheeks puff out when you play the recorder?","wrong_answer":"yes","correct_answer":"no; blow a gentle, steady stream"}'::jsonb, 'The child thinks more air needs bigger cheeks.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Play while looking in a mirror.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.CRAWL.M_SW_ARMS_TOGETHER', 'CREA.G5.PERFOR.SWIMMING.CRAWL', 'Thinks both arms pull at the same time.', '{"question":"In front crawl, how do the arms move?","wrong_answer":"Both together","correct_answer":"One after the other"}'::jsonb, 'The child mixes it with breaststroke.', 'Offer "Both together" next to the right answer and ask the question again in a new context.', 'Show on land.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.CRAWL.M_SW_FROG_KICK', 'CREA.G5.PERFOR.SWIMMING.CRAWL', 'Thinks the legs kick like a frog.', '{"question":"How do the legs kick in front crawl?","wrong_answer":"Like a frog","correct_answer":"Small quick up-and-down kicks"}'::jsonb, 'The child mixes it with breaststroke.', 'Offer "Like a frog" next to the right answer and ask the question again in a new context.', 'Practise on the pool edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.CRAWL.M_SW_LIFT_HEAD', 'CREA.G5.PERFOR.SWIMMING.CRAWL', 'Lifts the head forward to breathe.', '{"question":"How does the swimmer breathe in?","wrong_answer":"Lifts the head forward","correct_answer":"Turns the head to the side"}'::jsonb, 'The child wants to see ahead.', 'Offer "Lifts the head forward" next to the right answer and ask the question again in a new context.', 'Practise on the pool edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.CRAWL.M_SW_HOLD_BREATH', 'CREA.G5.PERFOR.SWIMMING.CRAWL', 'Holds the breath all the time.', '{"question":"What does the swimmer do with the breath under water?","wrong_answer":"Holds it","correct_answer":"Breathes out"}'::jsonb, 'The child is afraid of water.', 'Offer "Holds it" next to the right answer and ask the question again in a new context.', 'Blow bubbles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.POOL_SAFETY.M_SW_RUN_POOL', 'CREA.G5.PERFOR.SWIMMING.POOL_SAFETY', 'Thinks running on the pool side is fine.', '{"question":"What should you not do on the pool side?","wrong_answer":"Walk","correct_answer":"Run"}'::jsonb, 'The child is excited.', 'Offer "Walk" next to the right answer and ask the question again in a new context.', 'Walk the pool side slowly with the class and point at the wet, slippery floor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.POOL_SAFETY.M_SW_SWIM_ALONE', 'CREA.G5.PERFOR.SWIMMING.POOL_SAFETY', 'Thinks swimming alone is fine for a good swimmer.', '{"question":"When should a learner swim?","wrong_answer":"Alone, if a good swimmer","correct_answer":"Only when a teacher or lifeguard is watching"}'::jsonb, 'The child is confident.', 'Offer "Alone, if a good swimmer" next to the right answer and ask the question again in a new context.', 'Discuss why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.POOL_SAFETY.M_SW_NO_SHOWER', 'CREA.G5.PERFOR.SWIMMING.POOL_SAFETY', 'Thinks showering before swimming is not needed.', '{"question":"What should you do before getting into the pool?","wrong_answer":"Jump in","correct_answer":"Shower"}'::jsonb, 'The child sees no reason.', 'Offer "Jump in" next to the right answer and ask the question again in a new context.', 'Talk about keeping the water clean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.POOL_SAFETY.M_SW_DIVE_SHALLOW', 'CREA.G5.PERFOR.SWIMMING.POOL_SAFETY', 'Thinks diving in shallow water is fine.', '{"question":"How should you enter water of unknown depth?","wrong_answer":"Dive in","correct_answer":"Feet first"}'::jsonb, 'The child has seen others dive.', 'Offer "Dive in" next to the right answer and ask the question again in a new context.', 'Discuss injuries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES.M_SW_CG_ONLY_BOARD', 'CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES', 'Thinks all counting games are sit-down and give no exercise.', '{"question":"Which counting game is a moving game?","wrong_answer":"Bao only","correct_answer":"Skipping with counting"}'::jsonb, 'The child knows only bao.', 'Offer "Bao only" next to the right answer and ask the question again in a new context.', 'List counting games that move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES.M_SW_CG_NO_COUNT', 'CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES', 'Thinks counting is not part of a counting game.', '{"question":"What do players do in a counting game?","wrong_answer":"No counting","correct_answer":"Count seeds, steps or turns"}'::jsonb, 'The child thinks of just playing.', 'Offer "No counting" next to the right answer and ask the question again in a new context.', 'Play one and watch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES.M_SW_CG_RHYTHM_FAST', 'CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES', 'Thinks counting to rhythm means counting as fast as you can.', '{"question":"What does counting to a rhythm mean?","wrong_answer":"Counting as fast as possible","correct_answer":"Counting and moving to the beat"}'::jsonb, 'The child mixes rhythm with speed.', 'Offer "Counting as fast as possible" next to the right answer and ask the question again in a new context.', 'Clap the beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES.M_CA5_SW_CG_WIN_ONLY', 'CREA.G5.PERFOR.SWIMMING.COUNTING_GAMES', 'Thinks counting games are only about winning.', '{"question":"Name a benefit of indigenous counting games.","wrong_answer":"only winning","correct_answer":"any of: counting skill, coordination, fitness, teamwork"}'::jsonb, 'The child focuses on the score.', 'Offer "only winning" next to the right answer and ask the question again in a new context.', 'List what the body and mind do in one game.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_AP_CRIT_VAGUE', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Says only "nice" without a reason.', '{"question":"Which comment is the most helpful?","wrong_answer":"It is nice.","correct_answer":"I like the bright colours in the sky because they show a sunny day."}'::jsonb, 'The child does not know what to look at.', 'Offer "It is nice." next to the right answer and ask the question again in a new context.', 'Practise with a sentence starter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_AP_CRIT_RUDE', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Uses rude words about someone else''s work.', '{"question":"Which comment is polite?","wrong_answer":"This is ugly.","correct_answer":"I think more colour in the corner would make it stronger."}'::jsonb, 'The child thinks honest means harsh.', 'Offer "This is ugly." next to the right answer and ask the question again in a new context.', 'Practise kind wording.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_AP_CRIT_TOUCH', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Touches the artworks on display.', '{"question":"What should you do with a display piece?","wrong_answer":"Touch it to feel it","correct_answer":"Look carefully without touching"}'::jsonb, 'The child is curious.', 'Offer "Touch it to feel it" next to the right answer and ask the question again in a new context.', 'Set gallery rules.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS.M_AP_TERM_FORMATION_COSTUME', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS', 'Mixes up formation and costume.', '{"question":"Which word means the shape the dancers make?","wrong_answer":"Costume","correct_answer":"Formation"}'::jsonb, 'The child mixes up similar words.', 'Offer "Costume" next to the right answer and ask the question again in a new context.', 'Use each word in a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS.M_AP_TERM_SOLOIST_CHORUS', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS', 'Mixes up soloist and chorus.', '{"question":"Which word means the group that answers the leader?","wrong_answer":"Soloist","correct_answer":"Chorus"}'::jsonb, 'The child mixes up who leads.', 'Offer "Soloist" next to the right answer and ask the question again in a new context.', 'Role-play call and response.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS.M_AP_TERM_OCCASION_COMMUNITY', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS', 'Mixes up occasion and community.', '{"question":"Which word means when a dance is performed?","wrong_answer":"Community","correct_answer":"Occasion"}'::jsonb, 'The child mixes up when and who.', 'Offer "Community" next to the right answer and ask the question again in a new context.', 'Use each in a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_AP_ANTHEM_NATIONAL', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Thinks the EAC anthem is Kenya''s national anthem.', '{"question":"The East African Community Anthem is the anthem of which group?","wrong_answer":"Kenya only","correct_answer":"The East African Community, a group of countries"}'::jsonb, 'The child knows only one anthem.', 'Offer "Kenya only" next to the right answer and ask the question again in a new context.', 'Sing both and say who each belongs to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_AP_ANTHEM_SIT', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Thinks you may sit while the anthem is played.', '{"question":"What should you do while the anthem is sung?","wrong_answer":"Sit and talk","correct_answer":"Stand still and straight"}'::jsonb, 'The child does not know the etiquette.', 'Offer "Sit and talk" next to the right answer and ask the question again in a new context.', 'Practise standing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_AP_ANTHEM_VALUE', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Names a wrong value for the anthem (competition, rivalry).', '{"question":"Which value does the anthem ask for?","wrong_answer":"Rivalry between countries","correct_answer":"Unity and peace"}'::jsonb, 'The child thinks of sports teams.', 'Offer "Rivalry between countries" next to the right answer and ask the question again in a new context.', 'Read the words together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE.M_CA5_AP_CRIT_ONLY_PRAISE', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.CRITIQUE', 'Gives only praise and no idea for improving.', '{"question":"What makes a helpful critique?","wrong_answer":"only saying it is good","correct_answer":"saying what works and one kind idea to improve"}'::jsonb, 'The child fears hurting a friend.', 'Offer "only saying it is good" next to the right answer and ask the question again in a new context.', 'Use two stars and a wish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS.M_CA5_AP_TERM_PROP_ORNAMENT', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.FOLK_TERMS', 'Calls a fly whisk an ornament.', '{"question":"A dancer holds a fly whisk. Is it a prop or an ornament?","wrong_answer":"an ornament","correct_answer":"a prop"}'::jsonb, 'Both add to the look of the dance.', 'Offer "an ornament" next to the right answer and ask the question again in a new context.', 'Ask: is it worn or held?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM.M_CA5_AP_ANTHEM_LANGUAGE', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.ANTHEM', 'Thinks the EAC anthem is sung in English only.', '{"question":"In which language is the EAC anthem sung?","wrong_answer":"English","correct_answer":"Kiswahili"}'::jsonb, 'The child expects anthems for many countries to be in English.', 'Offer "English" next to the right answer and ask the question again in a new context.', 'Read the first line of the anthem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
